<script setup>
import {reactive,ref} from 'vue';import {ElMessage} from 'element-plus';import {register} from '../../api/auth.js'
const form=reactive({name:'',phone:'',password:'',agreement:false});const loading=ref(false),formRef=ref();const rules={name:[{required:true,message:'请输入称呼',trigger:'blur'}],phone:[{required:true,message:'请输入手机号',trigger:'blur'},{pattern:/^1\d{10}$/,message:'手机号格式不正确',trigger:'blur'}],password:[{required:true,min:6,message:'密码至少 6 位',trigger:'blur'}]};async function submit(){await formRef.value.validate();if(!form.agreement)return ElMessage.warning('请阅读并同意服务条款');loading.value=true;try{await register(form);ElMessage.success('注册成功');location.href='/workspace'}finally{loading.value=false}}
</script>
<template><div class="auth-shell"><div class="auth-visual register-visual"></div><div class="auth-panel"><div class="auth-box"><span class="eyebrow">建立定制档案</span><h1>创建客户账号</h1><p class="muted">保存需求，持续跟踪方案与交付进度</p><el-form ref="formRef" :model="form" :rules="rules" label-position="top" @submit.prevent="submit"><el-form-item label="您的称呼" prop="name"><el-input v-model="form.name" placeholder="例如：张先生"/></el-form-item><el-form-item label="手机号" prop="phone"><el-input v-model="form.phone"/></el-form-item><el-form-item label="设置密码" prop="password"><el-input v-model="form.password" type="password" show-password/></el-form-item><el-checkbox v-model="form.agreement" class="agreement">我已阅读并同意服务条款与隐私政策</el-checkbox><el-button type="primary" :loading="loading" native-type="submit" style="width:100%">注册并开始定制</el-button><p class="auth-switch">已有账号？<router-link to="/login">返回登录</router-link></p></el-form></div></div></div></template>
<style scoped>.register-visual{background-image:url('https://images.unsplash.com/photo-1616486338812-3dadae4b4ace?auto=format&fit=crop&w=1400&q=85')}.agreement{margin:0 0 20px}.auth-switch{text-align:center;color:var(--c-muted);margin-top:20px}.auth-switch a{color:var(--c-primary)}</style>
